<?php
require_once __DIR__.'/../includes/auth.php';$u=require_role('provider');$uid=(int)$u['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'add';if($action==='delete'){$id=(int)($_POST['id']??0);$s=db()->prepare("DELETE FROM provider_services WHERE id=? AND provider_user_id=?");$s->execute([$id,$uid]);flash('success','Service removed.');redirect('provider/services.php');}$sid=(int)($_POST['service_id']??0);try{$title=clean_text($_POST['title']??'',180,false,'Service title');$desc=clean_text($_POST['description']??'',5000,false,'Service description');$from=nullable_money($_POST['price_from']??null,'Starting price');$to=nullable_money($_POST['price_to']??null,'Maximum price');}catch(RuntimeException $e){$error=$e->getMessage();$sid=0;}if(!$sid){$error=$error??'Please select a service.';}elseif(!admin_count('SELECT COUNT(*) FROM services WHERE id=? AND is_active=1',[$sid])){$error='Please select an active service.';}elseif($from!==null&&$to!==null&&$to<$from){$error='Maximum price cannot be lower than minimum price.';}else{try{$s=db()->prepare("INSERT INTO provider_services(provider_user_id,service_id,title,description,price_from,price_to) VALUES(?,?,?,?,?,?)");$s->execute([$uid,$sid,$title?:null,$desc?:null,$from,$to]);flash('success','Service added successfully.');redirect('provider/services.php');}catch(PDOException $e){$error='This service is already on your profile.';}}}
$pg=pagination_window(20,40);$services=db()->query("SELECT s.id,s.name,c.name category FROM services s JOIN categories c ON c.id=s.category_id WHERE s.is_active=1 ORDER BY c.name,s.name LIMIT 500")->fetchAll();$st=db()->prepare("SELECT ps.id,ps.service_id,ps.title,ps.description,ps.price_from,ps.price_to,ps.created_at,s.name,c.name category FROM provider_services ps JOIN services s ON s.id=ps.service_id JOIN categories c ON c.id=s.category_id WHERE ps.provider_user_id=? ORDER BY ps.created_at DESC,ps.id DESC LIMIT ".($pg['per']+1)." OFFSET ".$pg['offset']);$st->execute([$uid]);$mine=$st->fetchAll();$hasNext=trim_page_results($mine,$pg['per']);$success=flash('success');release_session_lock();$pageTitle='My Services — LocalConnect';require __DIR__.'/../includes/header.php';?>
<div class="container py-5"><div class="row g-4"><div class="col-lg-5"><h1 class="fw-bold">My services</h1><p class="text-muted">Providers must list at least one service to appear for service-specific searches.</p><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="soft-card p-4"><?=csrf_field()?><input type="hidden" name="action" value="add"><label class="form-label">Service *</label><select class="form-select mb-3" name="service_id" required><option value="">Choose service</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['category'].' — '.$s['name'])?></option><?php endforeach;?></select><label class="form-label">Custom title</label><input class="form-control mb-3" name="title" maxlength="180" placeholder="e.g. Emergency wiring repair"><label class="form-label">Description</label><textarea class="form-control mb-3" name="description" maxlength="5000" rows="3"></textarea><div class="row g-2 mb-3"><div class="col"><input type="number" min="0" step=".01" class="form-control" name="price_from" placeholder="From ₹"></div><div class="col"><input type="number" min="0" step=".01" class="form-control" name="price_to" placeholder="To ₹"></div></div><button class="btn btn-primary">Add Service</button></form></div><div class="col-lg-7"><h4 class="mb-3">Listed services</h4><?php foreach($mine as $m):?><div class="service-row mb-3"><div class="d-flex justify-content-between gap-3"><div><strong><?=e($m['title']?:$m['name'])?></strong><div class="small text-muted"><?=e($m['category'].' · '.$m['name'])?></div><?php if($m['description']):?><p class="mb-1 mt-2"><?=e($m['description'])?></p><?php endif;?><small><?=$m['price_from']!==null?'From ₹'.number_format((float)$m['price_from'],0):'Price on request'?></small></div><form method="post" data-confirm-submit="Remove this service?"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></div></div><?php endforeach;?><?php if(!$mine):?><div class="soft-card p-4 text-center text-muted">No services on this page.</div><?php endif;?><?=pagination_nav($pg['page'],$hasNext)?></div></div></div><?php require __DIR__.'/../includes/footer.php';?>
